% Explicit faces: OAB, OAC, OBC, ABC. Visible faces OAC and OBC; hidden faces OAB and ABC. AB is the sole hidden edge.
\coordinate (A) at (0,0);
\coordinate (C) at (3,-1.3);
\coordinate (B) at (3.6,0.65);
\coordinate (O) at (2.15,3.3);
\coordinate (M) at ($(A)!0.5!(C)$);
\draw[line width=0.8pt,dash pattern=on 3pt off 3pt] (A)--(B);
\draw[line width=0.8pt] (O)--(A)--(C)--(B)--(O)--(C);
