\coordinate (TAM) at ($(A)!0.5!(M)$);
\coordinate (TMC) at ($(M)!0.5!(C)$);
\draw[line width=0.4pt] ($(TAM)!1.4mm!90:(C)$)--($(TAM)!1.4mm!-90:(C)$);
\draw[line width=0.4pt] ($(TMC)!1.4mm!90:(C)$)--($(TMC)!1.4mm!-90:(C)$);
